select distinct g.* from mxk_groups g left join mxk_group_member gm on gm.groupid = g.id and gm.instid = g.instid where g.status = 1 and (g.groupcode = 'ROLE_ALL_USER'
or gm.memberid in
#{item}
)

select distinct r.*
from mxk_roles r
left join mxk_role_member rm on rm.roleid = r.id and rm.instid = r.instid
where r.status = 1
  and r.appid = #{appId}
  and (r.rolecode = 'ROLE_ALL_USER'

  or rm.memberid in

      #{item}


  )

select distinct r.* from mxk_resources r join mxk_permission p on p.resourceid = r.id and p.appid = r.appid where r.appid = #{appId} and r.status = 1 and p.status = 1
and p.groupid in
#{item}

select distinct r.* from mxk_resources r join mxk_permission_role pr on pr.resourceid = r.id and pr.appid = r.appid where r.appid = #{appId} and r.status = 1 and pr.status = 1
and pr.roleid in
#{item}
